import{_ as e,c as o,o as s,a6 as r}from"./chunks/framework.BY05barL.js";const l="/ucasal-ssoo-estudio/assets/10-tarjetas-perforadas.DDS4rBe7.png",n="/ucasal-ssoo-estudio/assets/10-procesamiento-por-lotes.B8ldH4qV.png",t="/ucasal-ssoo-estudio/assets/10-lenguajes-programacion.BGBl2CnU.png",_=JSON.parse('{"title":"Computadoras de Segunda Generación y Procesamiento por Lotes","description":"","frontmatter":{},"headers":[],"relativePath":"unidad1/computadoras-segunda-generacion.md","filePath":"unidad1/computadoras-segunda-generacion.md"}'),i={name:"unidad1/computadoras-segunda-generacion.md"};function d(c,a,u,p,m,g){return s(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="computadoras-de-segunda-generacion-y-procesamiento-por-lotes" tabindex="-1">Computadoras de Segunda Generación y Procesamiento por Lotes <a class="header-anchor" href="#computadoras-de-segunda-generacion-y-procesamiento-por-lotes" aria-label="Permalink to &quot;Computadoras de Segunda Generación y Procesamiento por Lotes&quot;">​</a></h1><h2 id="procedimiento-en-las-computadoras-de-segunda-generacion" tabindex="-1">Procedimiento en las computadoras de segunda generación <a class="header-anchor" href="#procedimiento-en-las-computadoras-de-segunda-generacion" aria-label="Permalink to &quot;Procedimiento en las computadoras de segunda generación&quot;">​</a></h2><p>El proceso de ejecución de programas en las computadoras de segunda generación seguía estos pasos:</p><ol><li>El usuario escribe un programa en tarjetas perforadas</li><li>El usuario entrega las tarjetas al operador</li><li>El operador carga las tarjetas en el lector de tarjetas</li><li>El operador ejecuta el programa</li><li>El operador entrega los resultados al usuario</li><li>El usuario revisa los resultados</li></ol><p><img src="'+l+'" alt="Tarjetas Perforadas"></p><h2 id="procesamiento-por-lotes" tabindex="-1">Procesamiento por lotes <a class="header-anchor" href="#procesamiento-por-lotes" aria-label="Permalink to &quot;Procesamiento por lotes&quot;">​</a></h2><p>El procesamiento por lotes (batch processing) fue una técnica desarrollada para mejorar la eficiencia de las computadoras de segunda generación:</p><p><img src="'+n+'" alt="Procesamiento por lotes"></p><p>El proceso funcionaba de la siguiente manera:</p><ol><li>Programadores cargan las tarjetas en la 1401</li><li>La 1401 lee los lotes de trabajo y los guarda en una Cinta</li><li>El Operador lleva la Cinta de Entrada a la 7094</li><li>La 7094 realiza los cálculos</li><li>El Operador lleva la Cinta de Salida a la 1401</li><li>La 1401 imprime los resultados</li></ol><h2 id="procesamiento-en-la-actualidad" tabindex="-1">Procesamiento en la actualidad <a class="header-anchor" href="#procesamiento-en-la-actualidad" aria-label="Permalink to &quot;Procesamiento en la actualidad&quot;">​</a></h2><p>En contraste con las computadoras de segunda generación, el procesamiento en las computadoras actuales es mucho más directo:</p><ol><li>El usuario escribe un programa en un lenguaje de programación</li><li>El código se compila o interpreta a lenguaje máquina</li><li>El usuario ejecuta el programa</li></ol><p><img src="'+t+'" alt="Lenguajes de Programación"></p><h2 id="analogia-entre-las-computadoras-de-segunda-generacion-y-las-computadoras-actuales" tabindex="-1">Analogía entre las computadoras de segunda generación y las computadoras actuales <a class="header-anchor" href="#analogia-entre-las-computadoras-de-segunda-generacion-y-las-computadoras-actuales" aria-label="Permalink to &quot;Analogía entre las computadoras de segunda generación y las computadoras actuales&quot;">​</a></h2><p>A pesar de las diferencias, podemos establecer analogías entre los componentes y procesos:</p><ul><li><strong>Entrada de datos</strong><ul><li>Las Tarjetas Perforadas son el código fuente almacenado en Discos, o los datos ingresados mediante un Teclado, Mouse, etc.</li></ul></li><li><strong>Almacenamiento temporal</strong><ul><li>La Cinta Magnética es la Memoria RAM</li></ul></li><li><strong>Transferencia de datos</strong><ul><li>El movimiento físico de las Cintas es la transferencia de datos entre la CPU y la Memoria RAM</li></ul></li><li><strong>Procesamiento</strong><ul><li>La 7094 es la CPU</li></ul></li><li><strong>Almacenamiento de resultados</strong><ul><li>La escritura en Cintas es análoga a la escritura en Discos Duros o SSDs</li></ul></li><li><strong>Salida de datos</strong><ul><li>La impresión de resultados es la salida de datos en una pantalla o impresora</li></ul></li></ul>',17)])])}const P=e(i,[["render",d]]);export{_ as __pageData,P as default};
